package com.oms.dao;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;
public class ReconciliationDao{public record Document(long id,String code,long customerId,LocalDate start,LocalDate end,BigDecimal opening,BigDecimal increase,BigDecimal decrease,BigDecimal closing,String status,String reason){}public List<Document> list(Connection c,Long customer)throws SQLException{List<Document>x=new ArrayList<>();String sql="SELECT id,code,customer_id,period_start,period_end,opening_balance,increase_amount,decrease_amount,closing_balance,status,dispute_reason FROM debt_reconciliations"+(customer==null?"":" WHERE customer_id=?")+" ORDER BY period_start DESC,id DESC";try(var p=c.prepareStatement(sql)){if(customer!=null)p.setLong(1,customer);try(var r=p.executeQuery()){while(r.next())x.add(new Document(r.getLong(1),r.getString(2),r.getLong(3),r.getDate(4).toLocalDate(),r.getDate(5).toLocalDate(),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getString(10),r.getString(11)));}}return x;}public long next(Connection c)throws SQLException{long n;try(var p=c.prepareStatement("SELECT last_number FROM document_sequences WHERE name='RECONCILIATION' FOR UPDATE");var r=p.executeQuery()){if(!r.next())throw new SQLException("Thiếu dãy biên bản");n=r.getLong(1)+1;}try(var p=c.prepareStatement("UPDATE document_sequences SET last_number=? WHERE name='RECONCILIATION'")){p.setLong(1,n);p.executeUpdate();}return n;}public long insert(Connection c,String code,long customer,LocalDate start,LocalDate end,BigDecimal opening,BigDecimal increase,BigDecimal decrease,long actor)throws SQLException{try(var p=c.prepareStatement("INSERT INTO debt_reconciliations(code,customer_id,period_start,period_end,opening_balance,increase_amount,decrease_amount,closing_balance,created_by) VALUES(?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,code);p.setLong(2,customer);p.setDate(3,java.sql.Date.valueOf(start));p.setDate(4,java.sql.Date.valueOf(end));p.setBigDecimal(5,opening);p.setBigDecimal(6,increase);p.setBigDecimal(7,decrease);p.setBigDecimal(8,opening.add(increase).subtract(decrease));p.setLong(9,actor);p.executeUpdate();try(var r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}public void respond(Connection c,long id,long customer,String status,String reason)throws SQLException{try(var p=c.prepareStatement("UPDATE debt_reconciliations SET status=?,dispute_reason=?,responded_at=CURRENT_TIMESTAMP WHERE id=? AND customer_id=? AND status='PENDING'")){p.setString(1,status);p.setString(2,reason);p.setLong(3,id);p.setLong(4,customer);if(p.executeUpdate()!=1)throw new IllegalStateException("Biên bản đã phản hồi hoặc không tồn tại.");}}public Long portalCustomer(Connection c,long user)throws SQLException{try(var p=c.prepareStatement("SELECT customer_id FROM customer_accounts WHERE user_id=?")){p.setLong(1,user);try(var r=p.executeQuery()){return r.next()?r.getLong(1):null;}}}}
